  const [selectedTopic,setSelectedTopic]=useState(null);
  const [projectName,setProjectName]=useState('');
  const [showProjectForm,setShowProjectForm]=useState(false);
  const [focusSessions,setFocusSessions]=useState(()=>readStore('mahi_focus_sessions',[]));
  const [newTask,setNewTask]=useState('');
  const [integration,setIntegration]=useState(()=>{const saved=readStore('mahi_integrations',{});return {...{leetcodeUsername:'MahiVTech',youtubePlaylist:'https://youtube.com/playlist?list=PLmXKhU9FNesTaKDC-MKWt-rFuB8OwqrCY',aiEndpoint:'/api/chat'},...saved,leetcodeUsername:saved.leetcodeUsername||'MahiVTech',aiEndpoint:saved.aiEndpoint||'/api/chat'};});
  const [focusIntent,setFocusIntent]=useState('Study a concept');
  const [ytVideos,setYtVideos]=useState(()=>readStore('mahi_youtube_videos',[]));
  const [activeYtVideo,setActiveYtVideo]=useState(null);
  const [leetcodeStats,setLeetcodeStats]=useState(()=>readStore('mahi_leetcode_stats',null));
  const [integrationBusy,setIntegrationBusy]=useState(false);
  const [integrationStatus,setIntegrationStatus]=useState({loading:true,geminiConfigured:false,youtubeConfigured:false});
  const [projectDetail,setProjectDetail]=useState(null);
  const [projects,setProjects]=useState(()=>readStore('mahi_projects',[
    {name:'CampusOS AI',desc:'A student-focused academic operating system.',status:'In progress',stack:'React · AI'},
    {name:'MindSphere AI',desc:'A calm, supportive space for mindful routines.',status:'Planning',stack:'Next.js · FastAPI'}
  ]));
  useEffect(()=>{localStorage.setItem('mahi_tasks',JSON.stringify(tasks))},[tasks]);
  useEffect(()=>{localStorage.setItem('mahi_completed',JSON.stringify(completed))},[completed]);
  useEffect(()=>{localStorage.setItem('mahi_dark',JSON.stringify(dark))},[dark]);
  useEffect(()=>{localStorage.setItem('mahi_projects',JSON.stringify(projects))},[projects]);
  useEffect(()=>{localStorage.setItem('mahi_focus_sessions',JSON.stringify(focusSessions))},[focusSessions]);
  useEffect(()=>{localStorage.setItem('mahi_integrations',JSON.stringify(integration))},[integration]);
  useEffect(()=>{localStorage.setItem('mahi_youtube_videos',JSON.stringify(ytVideos))},[ytVideos]);
  useEffect(()=>{localStorage.setItem('mahi_leetcode_stats',JSON.stringify(leetcodeStats))},[leetcodeStats]);
  useEffect(()=>{localStorage.setItem('mahi_teacher_voice',JSON.stringify(voiceEnabled))},[voiceEnabled]);
  const refreshIntegrationStatus=async()=>{try{const r=await fetch('/api/status');const d=await r.json();if(!r.ok)throw new Error(d.error||'Status check failed');setIntegrationStatus({loading:false,...d});}catch{setIntegrationStatus({loading:false,geminiConfigured:false,youtubeConfigured:false,unavailable:true});}};
  useEffect(()=>{refreshIntegrationStatus();},[]);
  useEffect(()=>{if(!timerRunning)return;const id=setInterval(()=>setTimerSeconds(s=>{if(s===300&&timerMode==='Focus'){const line='Five minutes completed. Good work, Mahi. Keep your rhythm.';setTeacherMessage(line);if(voiceEnabled)speakTeacher(line);}if(s<=1){setTimerRunning(false);setFocusLock(false);if(timerMode==='Focus')setFocusSessions(prev=>[{id:Date.now(),date:new Date().toISOString(),minutes:25,mode:timerMode},...prev]);const line='You did it, Mahi. That was a full focus session. I’m proud of you.';setTeacherMessage(line);if(voiceEnabled)speakTeacher(line);setToast('Session complete — focus time logged!');return 0}return s-1}),1000);return()=>clearInterval(id)},[timerRunning, timerMode, voiceEnabled]);
  useEffect(()=>{if(!timerRunning)return;const warn=e=>{e.preventDefault();e.returnValue='Your focus session is still running.';return e.returnValue};window.addEventListener('beforeunload',warn);return()=>window.removeEventListener('beforeunload',warn)},[timerRunning]);
  useEffect(()=>{if(toast){const id=setTimeout(()=>setToast(''),2600);return()=>clearTimeout(id)}},[toast]);
